use std::cmp::min;

fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    // Determine how many more sessions each participant must be able to attend.
    // A participant is eligible if (5 - attendance_count) >= k,
    // which is equivalent to attendance_count <= 5 - k.
    let threshold = 5u8.saturating_sub(k);

    // Only consider up to the first `n` participants (or fewer if the vector is shorter).
    let limit = min(n as usize, participations.len());

    // Count how many participants are eligible.
    let eligible_count = participations
        .iter()
        .take(limit)
        .filter(|&&attended| attended <= threshold)
        .count();

    // Each team requires exactly 3 participants.
    // The maximum number of disjoint teams is eligible_count / 3.
    (eligible_count / 3) as u8
}

