    #[test]
    fn test_basic_cases() {
        // Example: n = 3, k = 2, participations = [3, 2, 1]
        // threshold = 5 - 2 = 3, all three are eligible => 3 / 3 = 1 team
        assert_eq!(solve(3, 2, vec![3, 2, 1]), 1);

        // n larger than vector length
        // threshold = 5 - 1 = 4, participations = [0, 1, 4] => all eligible, 3 / 3 = 1
        assert_eq!(solve(5, 1, vec![0, 1, 4]), 1);

        // n smaller than vector length
        // threshold = 5 - 2 = 3, only consider first 2 entries [0, 2], both eligible => 2 / 3 = 0
        assert_eq!(solve(2, 2, vec![0, 2, 3, 1]), 0);

        // No one eligible
        assert_eq!(solve(4, 5, vec![0, 1, 2, 3]), 0);

        // Eligible participants but not enough for a team
        assert_eq!(solve(4, 0, vec![5, 5, 5, 5]), 1); // All 4 can attend 0 more => 4/3 = 1
    }
